{"source":"#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    long long int n;
    scanf("%lld",&n);
    long long int i = 1;
    while (i <= n)
    {
        if (n - i > 0)
        {
            n = n - i;
            i++;
            continue;
        }
        else
        {
            printf("%lld", n);
            break;
        }
    }
    return 0;
}
